#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
#include <tuple>
using namespace std;

const int INF = INT_MAX;

struct Edge {
    int to, rev;
    int cap, cost;
};

vector<vector<Edge>> graph;
vector<int> visited, current, dist, potential;
int node_count;

int add_node() {
    graph.emplace_back();
    return node_count++;
}

void add_edge(int u, int v, int cap, int cost) {
    graph[u].push_back({v, (int)graph[v].size(), cap, cost});
    graph[v].push_back({u, (int)graph[u].size() - 1, 0, -cost});
}

bool dijkstra(int s, int t) {
    fill(dist.begin(), dist.end(), INF);
    fill(visited.begin(), visited.end(), 0);
    using P = pair<int, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push({dist[s] = 0, s});
    while (!pq.empty()) {
        auto [du, u] = pq.top(); pq.pop();
        if (visited[u]) continue;
        visited[u] = 1;
        for (auto& e : graph[u]) {
            int v = e.to;
            int dv = du + potential[u] + e.cost - potential[v];
            if (e.cap == 0 || visited[v] || dist[v] <= dv) continue;
            pq.push({dist[v] = dv, v});
        }
    }
    return visited[t];
}

bool dinic_bfs(int s, int t) {
    fill(visited.begin(), visited.end(), 0);
    queue<int> q;
    q.push(s);
    visited[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : graph[u]) {
            int v = e.to;
            if (visited[v] || e.cap == 0) continue;
            if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;
            visited[v] = visited[u] + 1;
            q.push(v);
        }
    }
    return visited[t];
}

int dinic_dfs(int u, int t, int f) {
    if (u == t) return f;
    int pushed = 0;
    for (int& i = current[u]; i < (int)graph[u].size(); ++i) {
        auto& e = graph[u][i];
        int v = e.to;
        if (e.cap == 0 || visited[v] != visited[u] + 1) continue;
        if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;
        int df = dinic_dfs(v, t, min(e.cap, f));
        pushed += df;
        f -= df;
        e.cap -= df;
        graph[v][e.rev].cap += df;
        if (f == 0) break;
    }
    return pushed;
}

pair<int, int> mincostflow(int s, int t, int mf) {
    int total_flow = 0, total_cost = 0;
    fill(potential.begin(), potential.end(), 0);
    while (dijkstra(s, t)) {
        int flow = 0;
        while (dinic_bfs(s, t)) {
            fill(current.begin(), current.end(), 0);
            int df = dinic_dfs(s, t, mf);
            mf -= df;
            flow += df;
            if (mf == 0) break;
        }
        total_flow += flow;
        total_cost += (dist[t] + potential[t]) * flow;
        for (int i = 0; i < node_count; ++i)
            potential[i] += dist[i];
        if (mf == 0) break;
    }
    return {total_flow, total_cost};
}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int layers = max(n, k) * 2;
    add_node();
    int s = add_node();
    int t = add_node();
    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        add_edge(s, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        for (int i = 0; i + 1 < layers; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                add_edge(u1, v1, 1, c + d * (2 * j + 1));
                add_edge(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < layers; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            add_edge(u, v, INF, c);
        }
    }
    for (int i = 0; i < layers; ++i)
        add_edge(i * n, t, INF, 0);
    printf("%d\n", mincostflow(s, t, INF).second);
    return 0;
}
